using System.Diagnostics;
using OpenTelemetry;
using OpenTelemetry.Trace;
using OpenTelemetry.Metrics;

public class TracedLlmClient
{
    private static readonly ActivitySource ActivitySource =
        new ActivitySource("EnterpriseNexus.AI", "1.0");

    private readonly IChatClient _inner;
    private readonly ILogger _logger;

    public async Task<ChatCompletion> CompleteAsync(
        string model, List<ChatMessage> messages, ChatOptions options, CancellationToken ct = default)
    {
        // Start a span for this LLM call
        using var activity = ActivitySource.StartActivity("llm.call")?;
        activity?.SetTag("gen_ai.system", "openai");
        activity?.SetTag("gen_ai.request.model", model);
        activity?.SetTag("gen_ai.request.temperature", options?.Temperature ?? 1.0);
        activity?.SetTag("gen_ai.request.max_tokens", options?.MaxOutputTokenCount);
        activity?.SetTag("server.address", "api.openai.com");

        // Record request messages as span events
        foreach (var msg in messages)
        {
            activity?.AddEvent(new ActivityEvent("gen_ai.prompt_message",
                default, new ActivityTagsCollection
                {
                    ["gen_ai.prompt.role"] = msg.Role.ToString(),
                    ["gen_ai.prompt.content"] = Truncate(msg.Text, 500)
                }));
        }

        var stopwatch = Stopwatch.StartNew();
        try
        {
            var response = await _inner.CompleteAsync(model, messages, options, ct);

            stopwatch.Stop();
            activity?.SetTag("gen_ai.usage.input_tokens", response.Usage?.InputTokenCount);
            activity?.SetTag("gen_ai.usage.output_tokens", response.Usage?.OutputTokenCount);
            activity?.SetTag("gen_ai.response.id", response.Id);
            activity?.SetTag("llm.duration_ms", stopwatch.ElapsedMilliseconds);

            // Record as metric for aggregation
            activity?.SetTag("llm.cost_usd", CalculateCost(response.Usage, model));

            return response;
        }
        catch (Exception ex)
        {
            activity?.SetStatus(ActivityStatusCode.Error, ex.Message);
            activity?.RecordException(ex);
            throw;
        }
    }
}

public class TracedRagPipeline
{
    private static readonly ActivitySource ActivitySource =
        new ActivitySource("EnterpriseNexus.RAG", "1.0");

    public async Task<string> QueryAsync(string question, CancellationToken ct)
    {
        using var trace = ActivitySource.StartActivity("rag.query")?;
        trace?.SetTag("rag.question", Truncate(question, 200));
        trace?.SetTag("rag.top_k", 5);

        // Step 1: Generate query embedding
        float[] embedding;
        using (var embedSpan = ActivitySource.StartActivity("rag.embed_query"))
        {
            var sw = Stopwatch.StartNew();
            embedding = await _embeddings.GenerateAsync(question, ct);
            embedSpan?.SetTag("embed.duration_ms", sw.ElapsedMilliseconds);
            embedSpan?.SetTag("embed.model", "text-embedding-3-small");
        }

        // Step 2: Vector search
        List<DocumentChunk> chunks;
        using (var searchSpan = ActivitySource.StartActivity("rag.vector_search"))
        {
            var sw = Stopwatch.StartNew();
            chunks = await _vectorStore.SearchAsync(embedding, topK: 5, ct);
            searchSpan?.SetTag("search.results_count", chunks.Count);
            searchSpan?.SetTag("search.duration_ms", sw.ElapsedMilliseconds);
        }

        // Step 3: Context assembly
        using var ctxSpan = ActivitySource.StartActivity("rag.context_assembly");
        var context = string.Join("\n---\n", chunks.Select(c => c.Content));
        ctxSpan?.SetTag("context.length_chars", context.Length);

        // Step 4: LLM generation
        string answer;
        using (var genSpan = ActivitySource.StartActivity("rag.llm_generation"))
        {
            var sw = Stopwatch.StartNew();
            answer = await _llmClient.CompleteAsync($"Context: {context}\n\nQuestion: {question}", ct);
            genSpan?.SetTag("generation.duration_ms", sw.ElapsedMilliseconds);
        }

        return answer;
    }
}
